struct Cantina {
  alimentos: Vec<Comida>,
  capacidade: usize
}

impl Cantina {
fn abastecer_cantina(&mut self, comidas: mut Vec<Comida>) {
   let fila = comidas.clone();
   while !comidas.is_empty() {
     if let Some(comida) = fila.pop() {
       self.alimentos.push(*comida);
     }
     else if fila.is_empty() { fila = comidas.clone(); }
   }
}
}
